def _parse_raw(raw: str) -> dict:
    out = {}
    for line in raw.strip().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        p = line.split("|")
        if len(p) < 10:
            continue
        slug = p[0]
        out[slug] = {
            "family": p[1],
            "noun": p[2],
            "problem": p[3],
            "audience": p[4],
            "tools": [x.strip() for x in p[5].split("،")],
            "signs": [p[6], p[7], p[8], p[9], p[10]],
            "mistakes": [p[11], p[12]],
            "types": [x.strip() for x in p[13].split("،")],
            "icon": p[14] if len(p) > 14 else "fa-tools",
        }
    return out


