FACTS = _parse_raw(RAW)
FACTS.update(_parse_raw(RAW2))


def family_of(slug: str) -> str:
    if slug in FACTS:
        return FACTS[slug]["family"]
    if any(x in slug for x in ("cleaning", "disinfection", "polishing")):
        return "cleaning"
    if any(x in slug for x in ("pest", "termite", "cockroach", "rodent", "mosquito", "pigeon", "bird", "ant", "bed-bug", "flea", "lizard", "snake", "scorpion")):
        return "pest"
    if any(x in slug for x in ("ac-", "freon", "cooling", "split-ac", "window-ac", "central-ac", "duct")):
        return "ac"
    if any(x in slug for x in ("paint", "wallpaper", "decor", "gypsum-board-decor")):
        return "paint"
    if any(x in slug for x in ("garden", "grass", "palm", "irrigation", "pergola", "fountain", "waterfall", "landscap")):
        return "garden"
    if any(x in slug for x in ("mov", "storage", "packaging", "piano")):
        return "moving"
    if "solar" in slug:
        return "solar"
    if any(x in slug for x in ("ship", "freight", "cargo", "parcel")):
        return "ship"
    if any(x in slug for x in ("plumber", "electric", "wiring", "heater", "drainage", "sanitary", "panel", "lighting", "pump")):
        return "elec"
    if any(x in slug for x in ("plumber", "electrician", "carpenter", "blacksmith", "painter", "tech", "24h")):
        return "tech"
    if any(x in slug for x in ("leak", "insulat", "waterproof", "humidity", "unclog", "septic")):
        return "leaks"
    if any(x in slug for x in ("renov", "inspection", "crack")):
        return "reno"
    if any(x in slug for x in ("maintenance", "hoods", "filters", "pumps", "chiller")):
        return "maintenance"
    return "install"
